/**
 * Pure corruption and restoration checks for the capsule-proving harness.
 *
 * A synthetic user's `corruptions.json` describes errors to plant in the
 * extracted memory files: a wrong number, an outdated value, a swapped person,
 * or a lost attribution. The runner applies them after extraction and later
 * asks whether consolidation against the original conversation restored each
 * line.
 *
 * Supported kinds (all generated by `synthetic/spec.mjs`):
 * - `number` / `outdated` / `swap-person`: `find` is replaced by `replace`.
 * - `attribution`: the line selected by `near` is rewritten so the statement
 *   reads as the user's own established fact, whichever source
 *   (`expectAttribution`: `document`, `assistant` or `user_belief`) it truly
 *   had. A recognised source phrase is replaced; otherwise the false
 *   attribution is prefixed after the bullet marker. That deterministic edit is
 *   documented here because attribution corruptions carry no `find`/`replace`.
 *
 * The module never mutates its input and has no dependencies.
 *
 * @module capsule-proving/run/corruptions
 */

/** A bullet or numbered list item. */
const BULLET_PATTERN = /^\s*(?:[-*+]|\d+[.)])\s+/;

/** A Markdown heading. */
const HEADING_PATTERN = /^\s*#{1,6}\s+/;

/**
 * Source phrases a memory line may use for each true attribution. The check is
 * deliberately small: a phrase it does not recognise is not guessed at, and
 * the attribution corruption falls back to prefixing the false source.
 *
 * @type {Record<string, RegExp>}
 */
const TRUE_ATTRIBUTION_PATTERNS = {
  user: /\b(?:the\s+)?user\b[^.\n]{0,40}\b(?:said|says|stated|states|reported|reports|mentioned|mentions|noted|notes|told)\b/i,
  user_belief: /\b(?:the\s+)?user\b[^.\n]{0,40}\b(?:believes|believed|thinks|thought|feels|felt|suspects|suspect|is of the opinion)\b/i,
  assistant: /\b(?:the\s+)?(?:assistant|model)\b[^.\n]{0,40}\b(?:suggested|suggests|recommended|recommends|advised|advises|proposed|proposes)\b/i,
  document: /\b(?:the\s+)?(?:document|report|notice|article|pamphlet|manual|file|label|leaflet)\b[^.\n]{0,40}\b(?:says|said|states|stated|claims|claimed|notes|noted|reports|reported|according to)\b/i,
};

/**
 * The false attribution written into the line for each true source. A
 * `document` claim, an assistant suggestion and a user belief are all promoted
 * to something the user established; the wording differs so a reader (and the
 * restoration check) can tell which promise was broken.
 *
 * @type {Record<string, string>}
 */
const WRONG_ATTRIBUTION = {
  user: 'the user states as their own fact',
  user_belief: 'established fact',
  assistant: 'the user decided this themselves',
  document: 'the user states as their own fact',
};

/** @param {unknown} value @returns {value is Record<string, any>} */
function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

/** @param {string} line @returns {boolean} */
function isBullet(line) {
  return BULLET_PATTERN.test(line);
}

/**
 * The block a line belongs to: its bullet with any continuation lines, or the
 * paragraph around it when it is not a list item. `near` may occur anywhere in
 * this block.
 *
 * @param {string[]} lines
 * @param {number} index
 * @returns {[number, number]} inclusive bounds
 */
function blockBounds(lines, index) {
  let start = index;
  if (!isBullet(lines[index])) {
    while (start > 0) {
      const previous = lines[start - 1];
      if (isBullet(previous)) {
        start -= 1;
        break;
      }
      if (previous.trim() === '' || HEADING_PATTERN.test(previous)) break;
      start -= 1;
    }
  }

  let end = index;
  if (isBullet(lines[start])) {
    while (end + 1 < lines.length) {
      const next = lines[end + 1];
      if (next.trim() === '' || isBullet(next) || HEADING_PATTERN.test(next)) break;
      end += 1;
    }
  }
  return [start, end];
}

/**
 * Find the first line that contains `find`, and when `near` is given also
 * contains or sits in the same bullet as `near`. Files are visited in the order
 * given; a corruption may name a `path` to restrict the search.
 *
 * @param {Record<string, string>} files
 * @param {string} find
 * @param {string | undefined} near
 * @param {string | undefined} onlyPath
 * @returns {{ path: string, index: number, lines: string[] } | null}
 */
function findLine(files, find, near, onlyPath) {
  const paths = onlyPath !== undefined ? [onlyPath] : Object.keys(files);
  for (const path of paths) {
    if (!Object.hasOwn(files, path)) continue;
    const lines = files[path].split('\n');
    for (let index = 0; index < lines.length; index += 1) {
      if (!lines[index].includes(find)) continue;
      if (near !== undefined) {
        const [start, end] = blockBounds(lines, index);
        if (!lines.slice(start, end + 1).some((line) => line.includes(near))) continue;
      }
      return { path, index, lines };
    }
  }
  return null;
}

/**
 * Insert a false attribution after a bullet marker, or at the start of the line.
 *
 * @param {string} line
 * @param {string} phrase
 * @returns {string}
 */
function prefixAttribution(line, phrase) {
  const bullet = line.match(/^(\s*(?:[-*+]|\d+[.)])\s+)/);
  if (bullet) return `${bullet[1]}${phrase}: ${line.slice(bullet[1].length)}`;
  const indent = line.match(/^(\s*)/)?.[1] ?? '';
  return `${indent}${phrase}: ${line.slice(indent.length)}`;
}

/**
 * Rewrite one line so its statement loses its true source.
 *
 * @param {string} line
 * @param {string} expectation one of `document`, `assistant`, `user_belief`, `user`
 * @returns {{ after: string, wrongPhrase: string, replaced: boolean }}
 */
function attributionEdit(line, expectation) {
  const wrongPhrase = WRONG_ATTRIBUTION[expectation] ?? 'the user states as their own fact';
  const pattern = TRUE_ATTRIBUTION_PATTERNS[expectation];
  const match = pattern ? pattern.exec(line) : null;
  if (match) {
    const replacement = `${wrongPhrase}:`;
    const withReplacement = match.index === 0
      ? `${wrongPhrase[0].toUpperCase()}${wrongPhrase.slice(1)}:`
      : replacement;
    return {
      after: `${line.slice(0, match.index)}${withReplacement}${line.slice(match.index + match[0].length)}`,
      wrongPhrase,
      replaced: true,
    };
  }
  return { after: prefixAttribution(line, wrongPhrase), wrongPhrase, replaced: false };
}

/**
 * Apply a corruption list to a map of memory files.
 *
 * Each result entry is `{ id, kind, path, line, before, after }`; `line` is
 * 1-based. Corruptions that cannot be placed deterministically are returned in
 * `skipped` with a reason and never guessed at.
 *
 * @param {Record<string, string>} files relative path → text
 * @param {Array<Record<string, any>>} corruptions
 * @returns {{ files: Record<string, string>, applied: Array<{ id: string, kind: string, path: string, line: number, before: string, after: string }>, skipped: Array<{ id: string, reason: string }> }}
 */
export function applyCorruptions(files, corruptions) {
  if (!isPlainObject(files)) throw new TypeError('files must be an object of relative path to text');
  if (!Array.isArray(corruptions)) throw new TypeError('corruptions must be an array');

  /** @type {Record<string, string>} */
  const out = { ...files };
  /** @type {Array<{ id: string, kind: string, path: string, line: number, before: string, after: string }>} */
  const applied = [];
  /** @type {Array<{ id: string, reason: string }>} */
  const skipped = [];

  for (const corruption of corruptions) {
    if (!isPlainObject(corruption)) {
      skipped.push({ id: '', reason: 'corruption is not an object' });
      continue;
    }
    const id = typeof corruption.id === 'string' ? corruption.id : '';
    const kind = typeof corruption.kind === 'string' ? corruption.kind : 'unknown';
    const onlyPath = typeof corruption.path === 'string' ? corruption.path : undefined;
    if (onlyPath !== undefined && !Object.hasOwn(out, onlyPath)) {
      skipped.push({ id, reason: `path not found: ${onlyPath}` });
      continue;
    }

    const find = typeof corruption.find === 'string' ? corruption.find : undefined;
    const replace = typeof corruption.replace === 'string' ? corruption.replace : undefined;
    const near = typeof corruption.near === 'string' ? corruption.near : undefined;

    if (find !== undefined && find !== '' && replace !== undefined) {
      const target = findLine(out, find, near, onlyPath);
      if (!target) {
        skipped.push({ id, reason: near === undefined ? `find text not found: ${find}` : `find and near text not found: ${find} / ${near}` });
        continue;
      }
      const before = target.lines[target.index];
      const offset = before.indexOf(find);
      const after = `${before.slice(0, offset)}${replace}${before.slice(offset + find.length)}`;
      target.lines[target.index] = after;
      out[target.path] = target.lines.join('\n');
      applied.push({ id, kind, path: target.path, line: target.index + 1, before, after });
      continue;
    }

    if (kind === 'attribution') {
      if (near === undefined || near === '') {
        skipped.push({ id, reason: 'attribution corruption needs near' });
        continue;
      }
      const expectation = typeof corruption.expectAttribution === 'string' ? corruption.expectAttribution : '';
      if (!Object.hasOwn(TRUE_ATTRIBUTION_PATTERNS, expectation)) {
        skipped.push({ id, reason: 'attribution corruption needs a known expectAttribution' });
        continue;
      }
      const target = findLine(out, near, undefined, onlyPath);
      if (!target) {
        skipped.push({ id, reason: `near text not found: ${near}` });
        continue;
      }
      const before = target.lines[target.index];
      const edit = attributionEdit(before, expectation);
      if (edit.after === before) {
        skipped.push({ id, reason: 'attribution edit would not change the line' });
        continue;
      }
      target.lines[target.index] = edit.after;
      out[target.path] = target.lines.join('\n');
      applied.push({ id, kind, path: target.path, line: target.index + 1, before, after: edit.after });
      continue;
    }

    if (find === undefined || find === '') {
      skipped.push({ id, reason: 'corruption has no find text' });
    } else {
      skipped.push({ id, reason: 'corruption has find but no replace' });
    }
  }

  return { files: out, applied, skipped };
}

/**
 * Check what happened to each planted corruption in a later snapshot.
 *
 * `restored` means the line again carries the original value or attribution;
 * `still_corrupt` means the corrupted value or attribution is still there (or
 * the line exists but proves neither); `line_gone` means the line no longer
 * exists in the file.
 *
 * @param {Record<string, string>} filesAfter
 * @param {Array<{ id: string, path: string, line: number, before: string, after: string }>} applied
 * @param {Array<Record<string, any>>} corruptions
 * @returns {Array<{ id: string, status: 'restored' | 'still_corrupt' | 'line_gone' }>}
 */
export function checkRestored(filesAfter, applied, corruptions) {
  if (!isPlainObject(filesAfter)) throw new TypeError('filesAfter must be an object of relative path to text');
  if (!Array.isArray(applied)) throw new TypeError('applied must be an array');
  if (!Array.isArray(corruptions)) throw new TypeError('corruptions must be an array');

  const appliedById = new Map();
  for (const entry of applied) {
    if (isPlainObject(entry) && typeof entry.id === 'string') appliedById.set(entry.id, entry);
  }
  const corruptionById = new Map();
  for (const entry of corruptions) {
    if (isPlainObject(entry) && typeof entry.id === 'string') corruptionById.set(entry.id, entry);
  }

  /** @type {Array<{ id: string, status: 'restored' | 'still_corrupt' | 'line_gone' }>} */
  const results = [];

  for (const [id, corruption] of corruptionById) {
    const planted = appliedById.get(id);
    if (!planted || typeof planted.path !== 'string' || !Object.hasOwn(filesAfter, planted.path)) {
      results.push({ id, status: 'line_gone' });
      continue;
    }

    const lines = filesAfter[planted.path].split('\n');
    const near = typeof corruption.near === 'string' ? corruption.near : undefined;
    const find = typeof corruption.find === 'string' ? corruption.find : undefined;
    const replace = typeof corruption.replace === 'string' ? corruption.replace : undefined;
    const restore = typeof corruption.restore === 'string' ? corruption.restore : find;

    /** @type {Set<number>} */
    const candidateIndexes = new Set();
    lines.forEach((line, index) => {
      if (near !== undefined && line.includes(near)) {
        candidateIndexes.add(index);
        const [start, end] = blockBounds(lines, index);
        for (let offset = start; offset <= end; offset += 1) candidateIndexes.add(offset);
      }
      if (find !== undefined && line.includes(find)) candidateIndexes.add(index);
      if (replace !== undefined && line.includes(replace)) candidateIndexes.add(index);
      if (restore !== undefined && restore !== find && line.includes(restore)) candidateIndexes.add(index);
    });
    const candidates = [...candidateIndexes].sort((a, b) => a - b).map((index) => lines[index]);

    if (candidates.length === 0) {
      if (lines.some((line) => line === planted.before)) results.push({ id, status: 'restored' });
      else if (lines.some((line) => line === planted.after)) results.push({ id, status: 'still_corrupt' });
      else results.push({ id, status: 'line_gone' });
      continue;
    }

    let restored = false;
    let stillCorrupt = false;

    if (corruption.kind === 'attribution') {
      const expectation = typeof corruption.expectAttribution === 'string' ? corruption.expectAttribution : '';
      const wrongPhrase = WRONG_ATTRIBUTION[expectation] ?? 'the user states as their own fact';
      const truePattern = TRUE_ATTRIBUTION_PATTERNS[expectation];
      for (const line of candidates) {
        if (line === planted.before) restored = true;
        else if (line === planted.after) stillCorrupt = true;
        else if (line.includes(wrongPhrase)) stillCorrupt = true;
        else if (truePattern && truePattern.test(line)) restored = true;
      }
    } else {
      for (const line of candidates) {
        const hasRestore = restore !== undefined && restore !== '' && line.includes(restore);
        const hasReplace = replace !== undefined && replace !== '' && line.includes(replace);
        if (line === planted.before) restored = true;
        else if (line === planted.after) stillCorrupt = true;
        else if (hasReplace && !hasRestore) stillCorrupt = true;
        else if (hasRestore && !hasReplace) restored = true;
      }
    }

    results.push({ id, status: restored && !stillCorrupt ? 'restored' : stillCorrupt ? 'still_corrupt' : 'line_gone' });
  }

  return results;
}
